using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class SuperstitionChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var b=new RainSuperstition();Require(!b.Hear(1,"chime",false)&&b.matches==0,"Already rainy music created a prediction");Require(b.Hear(1,"chime",true)&&!b.Hear(2,"chime",true)&&b.until==46,"Repeated notes extended a trial");Require(b.Observe(10,true)&&b.matches==1&&!b.Observe(11,true),"Rain paired twice");b.Hear(50,"chime",true);b.Observe(60,true);Require(b.Conviction>=.45f,"Repeated coincidences did not teach ritual");b.Hear(70,"chime",true);b.Observe(116,false);Require(b.Conviction<.45f,"Failed prediction did not weaken belief");for(int i=0;i<100;i++){b.Hear(200+i*50,"chime",true);b.Observe(201+i*50,true);}Require(b.Valid()&&b.matches+b.misses<=20,"Belief sample history unbounded");b.until=float.NaN;Require(!b.Valid(),"Bad deadline accepted");Debug.Log("BWVR_SUPERSTITION_MODEL_PASS");}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");VerifyModel();var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>().world;Require(!nav.TreeNavigationPending,"Wait for navigation");var culture=(VillageCulture)typeof(QuestSlice).GetField("culture",Flags).GetValue(slice);var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var music=slice.GetComponentInChildren<PlayerRhythm>();var mp=music.transform.position;var mr=music.transform.rotation;var shared=music.GetComponent<SharedRhythm>();var field=typeof(QuestSlice).GetField("state",Flags);var original=field.GetValue(slice);var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100};test.Hybrid.time=100;var actor=people[0].GetComponent<VillagerExploration>();
  void Phrase(){music.ResetWorld();test.Weather.rain=0;for(int i=0;i<4;i++){test.Hybrid.time+=.5f;Require(music.Tap(i%2),"Native chime tap rejected");}music.Cancel();}
  try{
   god.Interrupt("Superstition QA");field.SetValue(slice,test);god.NewSeason();foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();p.transform.position+=Vector3.up*nav.Scale*500;}slice.GetComponentInChildren<VillageFamilies>().ResetWorld();slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);var lane=slice.GetComponentInChildren<BeachBall>().Bowling;Require(nav.Sample(lane.Start,nav.creature,8,out var foot),"No music stage");god.transform.position=nav.ProjectFoot(foot,nav.creature);god.transform.rotation=Quaternion.LookRotation(lane.Forward);god.GetComponent<IslandNavigator>().ResetRoute();music.transform.position=god.transform.position+god.transform.forward*nav.Scale*10+Vector3.up*nav.Scale;var resources=slice.GetComponentInChildren<VillageResources>();bool seen=false;
   for(int i=0;i<24;i++){var wanted=music.transform.position+Quaternion.Euler(0,i*15,0)*Vector3.forward*nav.Scale*8;if(!nav.Sample(wanted,nav.villager,4,out var at))continue;people[0].transform.position=nav.ProjectFoot(at,nav.villager);people[0].transform.LookAt(new Vector3(music.transform.position.x,people[0].transform.position.y,music.transform.position.z));Physics.SyncTransforms();if(resources.ProvisionVisible(people[0],music.transform.position,music.transform)&&god.CanSeeCue(music.GetComponent<HybridTarget>(),false,true)){seen=true;break;}}Require(seen,"No visible music witness stage");
   Phrase();var belief=people[0].Memory.rainBelief;Require(belief?.until>test.Hybrid.time&&people[1].Memory.rainBelief==null,"Demonstration did not separate real listeners");test.Weather.rain=.5f;test.paused=true;culture.Advance();Require(belief.matches==0,"Paused observation learned weather");test.paused=false;culture.Advance();Require(belief.matches==1,"Rain did not pair with heard music");test.Hybrid.time+=50;Phrase();test.Weather.rain=.5f;culture.Advance();Require(belief.matches==2&&belief.Conviction>=.45f,"Second native coincidence did not build belief");
   test.water=20;test.Weather.rain=0;actor.ResetTask();actor.GetComponent<IslandNavigator>().ResetRoute();Require((bool)typeof(VillagerExploration).GetMethod("TryRainRitual",Flags).Invoke(actor,null)&&shared.Ritualist==actor&&!music.GetComponent<CreatureAffordance>().Available&&!music.Tap(0),"Ritual did not reserve instrument exclusively");string weather=JsonUtility.ToJson(test.weather);var atBefore=actor.transform.position;actor.Tick(5,true);Require(actor.transform.position==atBefore&&belief.rituals==0,"Paused ritual advanced");for(int i=0;i<600&&belief.rituals==0;i++){test.Hybrid.time+=.05f;actor.Tick(.05f,false);}Require(belief.rituals==1&&shared.Ritualist==null&&JsonUtility.ToJson(test.weather)==weather&&test.water==20,"Ritual failed / changed weather or water");
   actor.ResetTask();test.Hybrid.time+=46;culture.Advance();Require(belief.misses==1&&belief.Conviction<.45f,"Unsuccessful native ritual did not weaken confidence");belief.nextRitual=0;Require(!(bool)typeof(VillagerExploration).GetMethod("TryRainRitual",Flags).Invoke(actor,null),"Weak belief still scheduled ritual");belief.matches=4;belief.misses=0;Require((bool)typeof(VillagerExploration).GetMethod("TryRainRitual",Flags).Invoke(actor,null),"Cannot stage cancellation");music.GetComponent<CarryItem>().held=true;actor.Tick(.1f,false);Require(shared.Ritualist==null&&belief.rituals==1,"Taking instrument did not cancel without credit");music.GetComponent<CarryItem>().held=false;
   Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid()&&CulturalBookText.Read(test,1,null).text.Contains("rituals"),"Belief/ritual state did not save / read truthfully");Debug.Log("BWVR_SUPERSTITION_RUNTIME_PASS: witnessed native music, real weather observations, repetition/failure learning, autonomous ritual movement/notes, exclusive instrument lease, pause/carry cleanup and unchanged weather/resources");
  }finally{actor.ResetTask();music.GetComponent<CarryItem>().held=false;music.ResetWorld();music.transform.SetPositionAndRotation(mp,mr);for(int i=0;i<people.Length;i++){people[i].GetComponent<VillagerExploration>().ResetTask();people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}god.Interrupt("Superstition QA complete");god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();field.SetValue(slice,original);}
 }
}
}
